mapper.select:
select w.id, w.name, w.url, w.thumbnail, w.folder, (select count(1) from px_like_record lr where lr.item_id = w.id and lr.type = '3') as like_count, w.width, w.height, w.`order`, w.del_flag, w.version, w.create_by, w.create_time, w.update_by, w.update_time, w.remark from px_wallpaper w
w.del_flag = 0
and w.folder = #{folder}
and w.name like concat('%', #{name}, '%')
and w.version = #{version}
and w.folder not in
#{fid}
ORDER BY
w.name ASC like_count DESC, w.update_time DESC w.update_time DESC

select w.id, w.name, w.url, w.thumbnail, w.folder, (select count(1) from px_like_record lr where lr.item_id = w.id and lr.type = '3') as like_count, w.width, w.height, w.`order`, w.del_flag, w.version, w.create_by, w.create_time, w.update_by, w.update_time, w.remark from px_wallpaper w where w.del_flag = 0 and w.id in
#{id}
ORDER BY w.update_time DESC

mapper.update:
update px_wallpaper
name = #{name}, url = #{url}, thumbnail = #{thumbnail}, folder = #{folder}, like_count = #{likeCount}, width = #{width}, height = #{height}, `order` = #{order}, del_flag = #{delFlag}, version = #{version}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where id = #{id}

mapper.delete:
update px_wallpaper
set del_flag = 1
where id = #{id}

mapper.update:
update px_wallpaper
set like_count = GREATEST(0, like_count + #{delta})
where id = #{id}
